-- Set isolation level for a single transaction (PostgreSQL)
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  -- Both SELECTs see the same snapshot regardless of concurrent writes
  SELECT balance FROM accounts WHERE id = 1;  -- returns 1000
  -- (another tx commits balance = 900 here)
  SELECT balance FROM accounts WHERE id = 1;  -- still returns 1000
COMMIT;

-- Demonstrate phantom read scenario (Read Committed, no protection)
BEGIN;
  SELECT COUNT(*) FROM orders WHERE status = 'pending';  -- returns 5
  -- (another tx INSERTs a new pending order and commits)
  SELECT COUNT(*) FROM orders WHERE status = 'pending';  -- returns 6 (phantom!)
COMMIT;

-- Serializable: aborts on conflict instead of returning stale data
BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
  SELECT SUM(balance) FROM accounts;  -- reads snapshot
  INSERT INTO audit_log(total) VALUES (/* computed total */);
COMMIT;
